export const viewsR2={
 'river-falls':[['waterfall','Undercut & collapse'],['gorge','Upstream retreat'],['spurs','Interlocking spurs'],['cliff','River cliff'],['photo','High Force photo']],
 'river-deposits':[['floodplain','Flood plain'],['levee','Natural levees'],['bar','Point bar']],
 'river-meanders':[['banks','Two banks'],['neck','Narrowing neck'],['cutoff','Cut-through'],['oxbow','Isolated oxbow']],
 'river-floods':[['rural','Permeable ground'],['urban','Urban surfaces'],['farm','Compacted farmland'],['industry','Industry & exposure'],['graph','Compare hydrographs']],
 'river-management':[['reservoir','Dam & reservoir'],['channel','Channelisation'],['zoning','Floodplain zoning'],['washland','Washland']]
};
export const requirementsR2=Object.fromEntries(Object.entries(viewsR2).map(([k,v])=>[k,v.map(x=>x[0])]));
export const animatedR2=(k,v)=>!((k==='river-falls'&&['spurs','photo'].includes(v))||(k==='river-floods'&&v==='graph')||(k==='river-management'&&v==='zoning'));
export const storm={hours:[0,1,2,3,4,5,6],rain:[0,12,6,0,0,0,0],rural:[4,5,9,15,20,13,7],urban:[4,14,36,22,12,7,5]};
const text=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const dot=(x,y,r=4,c='#efd1b1')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const line=(path,c='#a6d6e3',w=3,extra='')=>`<path d="${path}" fill="none" stroke="${c}" stroke-width="${w}" ${extra}/>`;
const arrow=(x,y,a,b)=>line(`M${x} ${y}L${a} ${b}`,'#ed9b87',3,'marker-end="url(#r2Arrow)"');
const box=(x,y,w,h,s)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="7" fill="#334e64" stroke="#9ab5c0"/>`+text(x+8,y+21,s,12);
const wrap=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="r2Ground" x2="0" y2="1"><stop stop-color="#b5b69e"/><stop offset="1" stop-color="#7c8d83"/></linearGradient><marker id="r2Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#ed9b87"/></marker></defs><g font-family="sans-serif" fill="#edf1ec">${b}</g></svg><p class="geo-caption">${c}</p>`;
export function highForcePhoto(teaching=false){return `<figure style="margin:0 0 20px"><img src="./geography/images/high-force-gerrard.jpg" width="1600" height="900" style="display:block;width:100%;height:auto;border-radius:12px" alt="High Force: water drops over a dark steep rock face into a pool, with rock walls beside the downstream channel."><figcaption style="font-size:12px;line-height:1.7;margin-top:12px">High Force, River Tees · 29 September 2021 · <a href="https://commons.wikimedia.org/wiki/File:High_Force_Waterfall_(geograph_7027112).jpg" target="_blank" rel="noopener" style="color:inherit">Sandy Gerrard / Geograph</a> · <a href="https://creativecommons.org/licenses/by-sa/2.0/" target="_blank" rel="noopener" style="color:inherit">CC BY-SA 2.0</a> · unchanged.${teaching?' Look for the resistant lip and the rock faces. A single dated image cannot establish an erosion rate or show the whole geological history.':''}</figcaption></figure>`;}
export function hydrograph(){const x=i=>60+i*53,y=q=>302-q*3;let b=text(25,30,'INVENTED SAME-STORM COMPARISON',13)+text(25,174,'Discharge (m³/s)',12)+text(255,58,'Rainfall (mm/hour)',12);for(let i=0;i<=4;i++){const val=i*10,yy=y(val);b+=line(`M60 ${yy}H378`,'#587181',1)+text(30,yy+4,val,11);}b+=line('M60 182V302H378','#d9e7ea',2);storm.hours.forEach((h,i)=>{b+=`<rect x="${x(i)-8}" y="${140-storm.rain[i]*5}" width="16" height="${storm.rain[i]*5}" fill="#a9c5d3"/>`+text(x(i)-3,322,h,11);if(storm.rain[i])b+=text(x(i)-8,130-storm.rain[i]*5,storm.rain[i],11);});b+=line('M60 140H378','#9eb6c1',1);for(const [key,color,dash] of [['rural','#f1cf9c',''],['urban','#ed9b87','stroke-dasharray="8 4"']]){b+=line(storm[key].map((v,i)=>(i?'L':'M')+x(i)+' '+y(v)).join(' '),color,3,dash);storm[key].forEach((v,i)=>b+=dot(x(i),y(v),3,color));}b+=text(165,346,'Hours from start',12)+line('M180 163H205','#f1cf9c',3)+text(211,167,'Rural',11)+line('M270 163H295','#ed9b87',3,'stroke-dasharray="5 3"')+text(301,167,'Urban',11);
 return wrap(b,'Invented hourly teaching series. Rainfall bars: 0,12,6,0,0,0,0mm/hour. Discharge lines: rural4,5,9,15,20,13,7m³/s; urban4,14,36,22,12,7,5m³/s at hours0–6. Not observed UK data or a forecast.');}
const ground=(top=240)=>`<path d="M20 ${top}H150V290H280V${top}H420V325H20Z" fill="url(#r2Ground)"/>`;
const bend=()=>`<path d="M40 280C40 190 340 250 340 140S100 25 100 105" fill="none" stroke="#74a5b5" stroke-width="46" stroke-linecap="round"/>`;
export function sceneR2(kind,selected,t=0){const options=viewsR2[kind];if(!options)return '';const s=options.some(x=>x[0]===selected)?selected:options[0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!animatedR2(kind,s))t=0;if(s==='photo')return highForcePhoto(true);if(kind==='river-floods'&&s==='graph')return hydrograph();let b='',c='';
 if(kind==='river-falls'){
  if(s==='spurs'){b=text(25,30,'PLAN VIEW · valley-side projections')+'<path d="M25 70H140L265 125 140 170 255 230 140 280H25Z" fill="url(#r2Ground)"/><path d="M415 70H300L180 180 300 220 190 285H415Z" fill="url(#r2Ground)"/>'+line('M225 65Q325 120 230 150T235 235 255 310','#a6d6e3',9)+arrow(225,70,267,99)+text(25,330,'Alternating ridges · river winds around them',12);c='Interlocking spurs are alternating valley-side ridges. This still is a conceptual plan, not an OS map; height and distance are not measured.';}
  else if(s==='cliff'){b=text(25,30,'CROSS-CHANNEL VIEW · a bend')+ground(175)+`<path d="M150 210H280V290H150Z" fill="#70a1b3"/><path d="M280 290L340 210H420V325H280Z" fill="#d3ba91"/>`+line(`M148 175L${148-t*17} 270`,'#ed9b87',4)+text(25,70,'Outside: erosion',14)+text(250,70,'Inside: deposition',14)+arrow(140,85,145,170)+arrow(320,85,325,212);for(let i=0;i<7;i++)b+=dot(155+(t*100+i*18)%115,245+i%3*10);c='A steep river cliff develops at the eroding outer bank; a gentler point bar develops inside. Bank erosion is exaggerated and time is compressed.';}
  else {const retreat=s==='gorge',lip=retreat?270-t*95:250,under=s==='waterfall'?18+t*36:25; b=text(25,30,retreat?'SIDE VIEW · retreat goes upstream ←':'SIDE VIEW · loss of support')+`<path d="M20 135H${lip}V169H20Z" fill="#8b969c"/><path d="M20 169H${lip-under}V260H420V325H20Z" fill="url(#r2Ground)"/><path d="M20 125H${lip}V255H420" fill="none" stroke="#a5d7e3" stroke-width="10"/>`+text(25,105,'Resistant lip',13)+text(25,213,'Less resistant rock',13)+arrow(lip-12,70,lip-75,70)+text(25,55,'Upstream',11)+text(315,245,'Downstream',11);for(let i=0;i<9;i++)b+=dot(lip+Math.sin(i)*4,155+(t*120+i*15)%102,3,'#e0eef0');if(!retreat){b+=`<path d="M${lip-18} ${145+Math.max(0,t-.6)*220}l20 0 6 19-20 0Z" fill="#929a9b" stroke="#d2d9d8"/>`+text(285,190,'Plunge pool',12)+line('M270 263Q290 300 325 266','#a6d6e3',7);}else b+=line('M270 115V260','#e4c6b7',2,'stroke-dasharray="5 5"')+text(277,110,'Former lip',11);c=retreat?'Repeated erosion and collapse shift the fall upstream, leaving a gorge downstream of it. Dashed line marks the former lip; the replay resets the teaching scene, not nature.':'Water undercuts the less resistant rock, leaving an unsupported overhang that collapses. Hydraulic action and abrasion deepen the plunge pool. This generic geometry is not a measured High Force section.';}
 }
 if(kind==='river-deposits'){
  if(s==='bar'){b=text(25,30,'PLAN VIEW · inside versus outside')+bend()+`<path d="M225 173Q310 215 317 154" stroke="#dfc49b" stroke-width="21" fill="none"/>`+arrow(355,110,355,160)+text(28,315,'Outside bank: erosion',12)+text(25,60,'Inside bank: point bar',12);for(let i=0;i<8;i++)b+=dot(227+t*73,180+i%3*6,2.5);c='Sediment accumulates at the inside point bar while the outer bank erodes. Flow and grain paths are simplified; bank processes can coexist.';}
  else{const swell=Math.sin(t*Math.PI),level=255-swell*65;b=text(25,30,'CROSS-SECTION · repeated floods build deposits')+ground(235)+`<path d="M150 ${level}H280V290H150Z" fill="#74a5b5"/>`;if(level<235)b+=`<rect x="25" y="${level}" width="390" height="${235-level}" fill="#74a5b5" opacity=".65"/>`;if(s==='levee')b+=`<path d="M105 235L143 ${235-t*24} 150 235M280 235L286 ${235-t*24} 330 235" fill="#dfc49b" stroke="#dfc49b" stroke-width="4"/>`+text(25,75,'Coarse near banks',14)+text(260,75,'Fine farther away',14);else b+=`<path d="M25 ${235-t*10}H145M285 ${235-t*10}H415" stroke="#dfc49b" stroke-width="${2+t*8}"/>`+text(25,75,'Alluvium across the flooded valley floor',14);for(let i=0;i<8;i++){const side=i%2?-1:1,d=15+t*110+(i%4)*10;b+=dot(side<0?150-d:280+d,219+swell*7,i%4<2?4:2);}c=s==='levee'?'Coarser sediment is commonly deposited near the channel as overbank flow slows; finer particles can travel farther. Repeated events build natural levees. Grain sizes and bank heights are exaggerated.':'Floodwater spreads, loses transport capacity and leaves alluvium across the flood plain. Repeated deposition and channel migration build the broader floor over time; one replay is not its entire history.';}
 }
 if(kind==='river-meanders'){
  const stage=s==='banks'?0:s==='neck'?1:s==='cutoff'?2:3;b=text(25,30,'PLAN VIEW · follow the flow arrows')+'<rect x="20" y="55" width="400" height="255" rx="18" fill="#748b80"/>';
  const neck=stage===0?50:stage===1?50-t*26:24,top=180-neck/2,bot=180+neck/2;
  const loop=`M35 ${top}H150C210 ${top} 215 75 300 75C405 75 405 285 300 285C215 285 210 ${bot} 150 ${bot}H35`;
  b+=line(loop,'#78a9b8',22);
  if(stage===0){b+=line('M320 75Q389 90 388 150','#ed9b87',5)+line('M312 101Q356 115 360 150','#efd1b1',12)+text(48,90,'Outer: erode',12)+text(48,115,'Inner: deposit',12)+arrow(202,140,220,115)+dot(35+t*112,top,4);}
  if(stage===1){b+=line(`M35 ${top+12}H150M35 ${bot-12}H150`,'#ed9b87',2)+text(45,110,'Neck narrows',14)+arrow(105,130,105,top-2)+arrow(105,230,105,bot+2);}
  if(stage>=2){b+=line(`M35 ${top}H105V${bot}H35`, '#a9dce5',stage===2?6+t*17:23)+arrow(40,top,85,top)+arrow(85,bot,40,bot);if(stage===3){b+=`<path d="M145 153H165V180H145ZM145 181H165V208H145Z" fill="#d9bd91"/>`+dot(t<.4?35+t*175:t<.6?105:105-(t-.6)*175,t<.4?top:t<.6?top+(t-.4)*120:bot,4)+text(225,180,'Old loop',13)+text(225,201,'isolated',13);}else{b+=dot(105,top+t*(bot-top),4)+text(25,330,'High flow cuts a shorter route through the neck',12);}}
  c=stage===0?'Outer-bank erosion and inner-bank deposition shift the bend. The complete water motion is three-dimensional; this plan view simplifies secondary flow.':stage===1?'Approaching banks erode and narrow the neck. The river is still connected around its meander; a narrow neck alone is not an isolated oxbow.':stage===2?'During sufficiently high flow a shorter channel can cut through a narrow neck. Deposition has not yet completely sealed the old loop in this stage.':'Deposition plugs the entrances to the abandoned loop, leaving an oxbow lake. The active river follows the shorter route; the lake may later silt up. A five-second replay is not the real formation time.';
 }
 if(kind==='river-floods'){
  const built=['urban','industry'].includes(s),farm=s==='farm';b=text(25,30,'SIDE VIEW · same rain, changed land use')+'<path d="M20 135L310 235H420V325H20Z" fill="url(#r2Ground)"/><path d="M310 235H420V285H310Z" fill="#72a4b4"/>';
  if(built){b+=line('M35 137L285 220','#ddd5cd',9)+box(65,90,65,55,s==='industry'?'Factory':'Homes')+box(170,125,60,48,s==='industry'?'Stores':'Roads')+line('M90 150L320 248','#ed9b87',5);for(let i=0;i<7;i++)b+=dot(75+(t*230+i*30)%230,150+((t*230+i*30)%230)*.4,3,'#d9ecf1');}
  else{for(let i=0;i<6;i++)b+=`<path d="M${40+i*43} ${130+i*15}l-7-22 14 0Z" fill="${farm?'#d2c294':'#adcbab'}"/>`;for(let i=0;i<8;i++){const x=50+i*27; b+=dot(x,150+i*9+t*(farm?15:55),3,'#d9ecf1');}if(farm)b+=line('M40 145L285 227','#d2b197',7);}
  for(let i=0;i<10;i++)b+=line(`M${40+i*31} ${48+(t*55+i*6)%50}l-3 10`,'#b9dce5',2);b+=text(25,310,built?'Connected runoff → channel + exposed assets':farm?'Compaction can restrict infiltration':'Infiltration and slower pathways',12);
  c=s==='rural'?'Rain can infiltrate permeable ground and take slower pathways to the river. Storage is finite and depends on soil, rock and previous conditions; rural land can still flood.':s==='urban'?'Impermeable roofs and roads connected to drains can send runoff to the river faster, increasing peak response under comparable conditions. Sustainable drainage can modify this.':s==='farm'?'Compacted agricultural soil can restrict infiltration and increase quick runoff. Effects vary with soil, farming practice, vegetation and drainage; farming is not one uniform surface.':'Industrial surfaces and drains can accelerate runoff; buildings and infrastructure also increase exposure. Floodwater can interrupt businesses, contaminate water and damage assets, as well as erode and deposit sediment.';
 }
 if(kind==='river-management'){
  b=text(25,30,'CONCEPTUAL SCENARIO · finite capacity')+'<path d="M20 260H420V325H20Z" fill="url(#r2Ground)"/>';
  if(s==='reservoir'){b+=`<path d="M25 ${165-t*35}H220V260H25Z" fill="#70a3b6"/><path d="M210 115H235L250 260H205Z" fill="#b4bdc1"/>`+line('M240 248H410','#a9d9e4',12)+text(35,90,'Store incoming water',14)+text(250,215,'Controlled release',12)+arrow(40,120,165,120)+dot(255+t*140,248,4)+line('M25 125H205','#ed9b87',2,'stroke-dasharray="5 4"');c='A reservoir stores some incoming water and releases it more gradually if operating rules and available capacity permit. The dashed limit highlights finite storage. Dams alter habitats and sediment transfer and can inundate land; no flood protection percentage is implied.';}
  else if(s==='channel'){b+=line('M25 140Q110 60 195 140T405 140','#6b8c9a',18,'stroke-dasharray="6 4"')+line('M25 140H405','#9dcbd7',24)+dot(30+t*370,140,5)+box(285,185,95,38,'Downstream')+text(25,85,'Former bends: dashed',13)+text(25,115,'Straightened channel',13)+arrow(275,140,365,140);c='Straightening illustrates one form of channelisation. Conveyance may improve locally, but faster delivery can transfer a peak or risk downstream. Widening, deepening and reinforcement also change channel form and habitats; this is not a guarantee of a particular outcome.';}
  else if(s==='zoning'){b+='<rect x="25" y="90" width="390" height="155" rx="10" fill="#6595a5" opacity=".5"/>'+line('M25 180H415','#a9d9e4',20)+box(45,255,90,40,'New housing')+text(45,75,'Flood-prone land: keep vulnerable uses away',12)+text(195,285,'Higher ground / safer site',12);c='Floodplain zoning locates vulnerable new development away from higher-risk land, reducing exposure. It does not stop rain or prevent the river from flooding; existing buildings and other residual risks still need attention.';}
  else{const fill=Math.sin(t*Math.PI);b+=line('M25 165H415','#a9d9e4',18)+`<path d="M85 215H245V265H85Z" fill="#6f8d78"/><path d="M85 ${263-fill*42}H245V265H85Z" fill="#87bccb"/>`+line('M110 165V215','#a9d9e4',5)+line('M245 250L300 165','#a9d9e4',4)+text(90,295,'Temporary washland',13)+text(25,90,'Store a peak · release as conditions allow',13)+dot(110,166+t*48,4);c='A washland temporarily stores floodwater, then releases it as conditions allow. Capacity and land availability are finite; storage can disrupt farming or recreation and needs agreements. This schematic does not claim every washland has these inlet/outlet structures.';}
 }
 return wrap(b,c);
}
